/* Return the n-th Fibonacci number (F(0)=0, F(1)=1). */
unsigned long long fibonacci(unsigned int n) {
    unsigned long long a = 0, b = 1;
    for (unsigned int i = 0; i < n; i++) {
        unsigned long long next = a + b;
        a = b;
        b = next;
    }
    return a;
}

